<script setup lang="ts">
import {onMounted,ref,reactive} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,query,download,errorMessage} from '../api/http'
const router=useRouter();const form=reactive({invoiceNo:'',model:'',equipment:'',customer:'',dateFrom:'',dateTo:''});const records=ref<any[]>([]),total=ref(0),page=ref(1),busy=ref(false)
async function load(){busy.value=true;try{const data=await api<any>('/exports?'+query({...form,page:page.value-1,size:20}));records.value=data.rows;total.value=data.total}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
function reset(){Object.assign(form,{invoiceNo:'',model:'',equipment:'',customer:'',dateFrom:'',dateTo:''});page.value=1;load()}
async function csv(){try{await download('/exports/export.csv?'+query(form),'export-records.csv')}catch(e){ElMessage.error(errorMessage(e))}}
function printList(){window.print()}
onMounted(load)
</script>
<template><h1 class="page-title">輸出管理</h1><section class="panel"><header class="panel-heading">検索条件</header><div class="panel-body"><el-form label-position="top"><el-row :gutter="16"><el-col :span="8"><el-form-item label="Invoice No."><el-input v-model="form.invoiceNo" clearable/></el-form-item></el-col><el-col :span="8"><el-form-item label="設備名"><el-input v-model="form.equipment" clearable/></el-form-item></el-col><el-col :span="8"><el-form-item label="型番"><el-input v-model="form.model" clearable/></el-form-item></el-col><el-col :span="8"><el-form-item label="取引先"><el-input v-model="form.customer" clearable/></el-form-item></el-col><el-col :span="8"><el-form-item label="出荷日（開始）"><el-date-picker v-model="form.dateFrom" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="出荷日（終了）"><el-date-picker v-model="form.dateTo" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col></el-row><div class="actions"><el-button type="primary" @click="page=1;load()">検索</el-button><el-button @click="reset">クリア</el-button></div></el-form></div></section><section class="panel"><header class="panel-heading toolbar" style="margin:0"><span>検索結果一覧（{{total}} 件）</span><div class="actions"><el-button @click="csv">CSV出力</el-button><el-button @click="printList">一覧印刷</el-button></div></header><div class="panel-body"><div class="scrollable-table"><el-table v-loading="busy" :data="records" stripe border><el-table-column prop="export_no" label="輸出No." min-width="130"/><el-table-column prop="invoice_no" label="Invoice No." min-width="140"/><el-table-column prop="export_date" label="出荷日" width="118"/><el-table-column prop="equipment" label="設備名" min-width="175" show-overflow-tooltip/><el-table-column prop="models" label="型番" min-width="105"/><el-table-column prop="customer_name" label="取引先" min-width="155" show-overflow-tooltip/><el-table-column prop="containers" label="Container" min-width="185"/><el-table-column label="操作" width="94" fixed="right"><template #default="scope"><el-button size="small" type="primary" plain @click="router.push('/exports/'+scope.row.export_id)">詳細</el-button></template></el-table-column></el-table></div><div style="margin-top:15px;display:flex;justify-content:flex-end"><el-pagination v-model:current-page="page" :page-size="20" layout="prev,pager,next" :total="total" @current-change="load"/></div><p class="data-note">Container 表示包含记录依据：PLANNED（计划）、DOCUMENTED（单据记载）、ACTUAL（已核实）。</p></div></section></template>
